-- ─── Capture the BEFORE state in transaction-local settings (no temp table, nothing printed) ───
DO $$
DECLARE
  v_pairs jsonb := '[["visitncy_beaches","kervansaray-beach","Kervansaray Beach"],["visitncy_beaches","long-beach","Long Beach"],["osm","way/225386412","Bamboo Beach"],["osm","way/608212204","Bella Marin Beach"],["osm","way/225382750","Camelot Beach"],["osm","way/1484271058","Chamada Beach Club"],["osm","way/286275732","Diana Beach"],["osm","way/603986283","Esentepe Belediye Halk Plajı"],["osm","way/208150337","Karaoğlanoğlu Plajı"],["osm","way/286276160","Korenium beach"],["osm","way/208111924","Lapta Belediye Plajı"],["osm","way/229043037","Lido Cyprus"],["osm","way/225383964","Municipality of Alsancak Beach"],["osm","way/244561269","Riviera Beach"],["osm","node/11994931556","Sandouka Beach"],["osm","way/208241783","Sardunya Beach"],["osm","way/666114116","Shayna"],["osm","node/11231014679","Suna''s Beach and Restaurant"],["osm","way/435771323","Kocareis Beach"],["osm","relation/15456405","Makenzi Plajı"],["osm","way/606238631","Silver Beach"],["osm","way/1365670207","Yeni Boğaziçi Halk Plajı"],["osm","way/309623318","Kaplıca Plajı"],["osm","way/1395325670","Lefke Belediyesi Halk Plajı"],["osm","way/952236170","Ayfilon Plajı"],["osm","relation/13040159","Club Di Mare"],["osm","node/1951274050","Honey Beach - Balcı Plaza"],["osm","way/510986434","Issız Plaj"],["osm","way/435772839","Mehmetçik Belediye Bafra Plajı"],["osm","way/603896219","Yudi Halk Plajı"]]'::jsonb;
  v_before jsonb;
BEGIN
  SELECT jsonb_build_object(
    'pairs', v_pairs,
    'total',   (SELECT count(*) FROM public.places),
    'present', (SELECT count(*) FROM public.places p WHERE EXISTS (
                  SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id)),
    'nb_n',  (SELECT count(*) FROM public.places WHERE category IS DISTINCT FROM 'beach'),
    'nb_md5', (SELECT md5(coalesce(string_agg(to_jsonb(p)::text, '|' ORDER BY p.id), '')) FROM public.places p WHERE p.category IS DISTINCT FROM 'beach'),
    'ob_n',  (SELECT count(*) FROM public.places p WHERE p.category IS NOT DISTINCT FROM 'beach' AND NOT EXISTS (
                SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id)),
    'ob_md5', (SELECT md5(coalesce(string_agg(to_jsonb(p)::text, '|' ORDER BY p.id), '')) FROM public.places p WHERE p.category IS NOT DISTINCT FROM 'beach' AND NOT EXISTS (
                SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id)),
    'act_n', (SELECT count(*) FROM public.places WHERE status IS NOT DISTINCT FROM 'active'),
    'act_md5', (SELECT md5(coalesce(string_agg(to_jsonb(p)::text, '|' ORDER BY p.id), '')) FROM public.places p WHERE p.status IS NOT DISTINCT FROM 'active')
  ) INTO v_before;
  PERFORM set_config('ada.beaches_before', v_before::text, true);
