  END IF;
END $$;

INSERT INTO public.places (name, name_i18n, description_i18n, category, region, area, latitude, longitude, access_type, amenities, source, source_id, status)
VALUES
  ('Kervansaray Beach', '{"en":"Kervansaray Beach","tr":"Kervansaray Plajı","ar":"شاطئ كرفانسراي","ru":"Пляж Кервансарай","el":"Παραλία Κερβανσαράι","fr":"Plage de Kervansaray","es":"Playa de Kervansaray","de":"Kervansaray-Strand","fa":"ساحل کاروانسرای"}'::jsonb, '{"en":"Operated by the Municipality of Kyrenia, this is a popular public leisure area in the Kervansaray area. It has sunbeds and umbrellas, dressing rooms and showers, restaurants, a car park for the disabled with easy access to the beach, and a swimming area marked off by buoys. There is a lifeguard tower with first aid.","tr":"Girne Belediyesi tarafından işletilen, Kervansaray bölgesinde herkesin yararlanabileceği gözde bir dinlence alanıdır. Şezlong ve şemsiyeler, soyunma kabinleri ve duşlar, restoranlar, plaja kolay erişimi olan bir engelli otoparkı ve şamandıralarla ayrılmış bir yüzme alanı bulunur. Ayrıca ilk yardım olanağı bulunan bir cankurtaran kulesi vardır.","ar":"تديرها بلدية كيرينيا، وهي منطقة ترفيهية شهيرة مفتوحة للجمهور في منطقة كرفانسراي. تتوفر فيها كراسي الاستلقاء والمظلات وغرف تبديل الملابس والاستحمام والمطاعم وموقف سيارات للأشخاص ذوي الإعاقة مع وصول سهل إلى الشاطئ ومنطقة سباحة محددة بالعوامات. ويوجد برج لإنقاذ الغرقى مزوّد بالإسعافات الأولية.","ru":"Пляж находится в ведении муниципалитета Кирении. Это популярная зона отдыха, открытая для всех, в районе Кервансарай. Здесь есть шезлонги и зонты, раздевалки и душевые, рестораны, парковка для людей с ограниченными возможностями с удобным доступом к пляжу и зона для купания, огороженная буями. Есть спасательная вышка с пунктом первой помощи.","el":"Λειτουργεί από τον Δήμο Κερύνειας και είναι ένας δημοφιλής χώρος αναψυχής ανοιχτός στο κοινό, στην περιοχή Κερβανσαράι. Διαθέτει ξαπλώστρες και ομπρέλες, αποδυτήρια και ντους, εστιατόρια, χώρο στάθμευσης για άτομα με αναπηρία με εύκολη πρόσβαση στην παραλία και ζώνη κολύμβησης οριοθετημένη με σημαδούρες. Υπάρχει πύργος ναυαγοσωστών με πρώτες βοήθειες.","fr":"Gérée par la municipalité de Kyrenia, c''est une zone de loisirs populaire, ouverte au public, dans le quartier de Kervansaray. On y trouve des transats et des parasols, des cabines de change et des douches, des restaurants, un parking pour personnes handicapées avec un accès facile à la plage et une zone de baignade délimitée par des bouées. Elle dispose d''une tour de surveillance avec poste de premiers secours.","es":"Gestionada por el municipio de Kyrenia, es una popular zona de ocio abierta al público, en la zona de Kervansaray. Cuenta con tumbonas y sombrillas, vestuarios y duchas, restaurantes, un aparcamiento para personas con discapacidad con fácil acceso a la playa y una zona de baño delimitada con boyas. Dispone de una torre de socorrismo con primeros auxilios.","de":"Der Strand wird von der Gemeinde Kyrenia betrieben und ist ein beliebtes Freizeitgelände für die Öffentlichkeit im Gebiet Kervansaray. Es gibt Liegen und Sonnenschirme, Umkleidekabinen und Duschen, Restaurants, einen Parkplatz für Menschen mit Behinderung mit leichtem Zugang zum Strand und einen durch Bojen abgetrennten Badebereich. Ein Rettungsturm mit Erste-Hilfe-Station ist vorhanden.","fa":"این ساحل را شهرداری کیرنیا اداره می‌کند و منطقه‌ای تفریحی و محبوب برای عموم در محدوده کاروانسرای است. در آن تخت‌های آفتابی و چتر، رختکن و دوش، رستوران، پارکینگ ویژه افراد دارای معلولیت با دسترسی آسان به ساحل و محدوده شنای مشخص‌شده با شناور وجود دارد. یک برج نجات‌غریق همراه با کمک‌های اولیه نیز در آن هست."}'::jsonb, 'beach', 'kyrenia', NULL, 35.347758, 33.255979, 'public', ARRAY['sunbeds', 'food_bar', 'lifeguard']::text[], 'visitncy_beaches', 'kervansaray-beach', 'staged'),
  ('Long Beach', '{"en":"Long Beach","tr":"Long Beach","ar":"Long Beach","ru":"Long Beach","el":"Long Beach","fr":"Long Beach","es":"Long Beach","de":"Long Beach","fa":"Long Beach"}'::jsonb, '{"en":"Situated on Salamis Bay, 15 km north of Famagusta and near the ruins of Salamis, this sandy beach offers a range of facilities. A shuttle service runs from town to the beach.","tr":"Salamis Körfezi''nde, Gazimağusa''nın 15 km kuzeyinde ve Salamis kalıntılarına yakın konumdaki bu kumsal plaj, çeşitli olanaklar sunar. Şehirden plaja bir servis hizmeti de işler.","ar":"يقع على خليج سلاميس، على بعد 15 كم شمال فاماغوستا وبالقرب من آثار سلاميس، وهو شاطئ رملي يوفر مجموعة من المرافق. وتعمل خدمة نقل مكوكية من المدينة إلى الشاطئ.","ru":"Этот песчаный пляж находится в Саламинском заливе, в 15 км к северу от Фамагусты, рядом с руинами Саламина, и предлагает ряд удобств. От города до пляжа курсирует трансфер.","el":"Αυτή η αμμώδης παραλία βρίσκεται στον κόλπο της Σαλαμίνας, 15 χλμ. βόρεια της Αμμοχώστου και κοντά στα ερείπια της Σαλαμίνας, και προσφέρει μια σειρά από παροχές. Λειτουργεί υπηρεσία μεταφοράς από την πόλη προς την παραλία.","fr":"Située sur la baie de Salamine, à 15 km au nord de Famagouste et près des ruines de Salamine, cette plage de sable propose un éventail d''équipements. Un service de navette relie la ville à la plage.","es":"Situada en la bahía de Salamina, a 15 km al norte de Famagusta y cerca de las ruinas de Salamina, esta playa de arena ofrece una variedad de instalaciones. Hay un servicio de autobús lanzadera desde la ciudad hasta la playa.","de":"Der Sandstrand liegt an der Bucht von Salamis, 15 km nördlich von Famagusta und in der Nähe der Ruinen von Salamis, und bietet eine Reihe von Einrichtungen. Ein Shuttleservice fährt von der Stadt zum Strand.","fa":"این ساحل ماسه‌ای در خلیج سالامیس، 15 کیلومتر شمال فاماگوستا و نزدیک خرابه‌های سالامیس قرار دارد و امکانات متنوعی ارائه می‌دهد. یک سرویس شاتل نیز از شهر به ساحل رفت‌وآمد می‌کند."}'::jsonb, 'beach', 'iskele', 'long-beach', 35.266136, 33.915938, 'public', NULL, 'visitncy_beaches', 'long-beach', 'staged'),
