-- ─── Assertions a, b, c ───
DO $$
DECLARE
  b jsonb := current_setting('ada.beaches_before')::jsonb;
  v_pairs jsonb := b->'pairs';
  v_expect int := 30;
  v_min int := 2;
  v_found int; v_present_after int; v_total_after bigint; v_added int;
  v_n bigint; v_md5 text;
BEGIN
  -- a. every pair exists once, as a beach, staged or (after a later publish) active
  SELECT count(*) INTO v_present_after FROM public.places p WHERE EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id);
  SELECT count(*) INTO v_found FROM public.places p WHERE p.category IS NOT DISTINCT FROM 'beach' AND p.status IN ('staged', 'active') AND EXISTS (
    SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id);
  IF jsonb_array_length(v_pairs) <> v_expect THEN RAISE EXCEPTION 'pair list holds % pairs, expected %', jsonb_array_length(v_pairs), v_expect; END IF;
  IF v_present_after <> v_expect THEN RAISE EXCEPTION 'expected % rows for this file, found % (a pair is missing or its row is not a beach)', v_expect, v_present_after; END IF;
  IF v_found <> v_expect THEN RAISE EXCEPTION '% of % rows are not category beach with status staged or active', v_expect - v_found, v_expect; END IF;

  -- b. scope: nothing but this file's rows changed, and nothing was published
  SELECT count(*), md5(coalesce(string_agg(to_jsonb(p)::text, '|' ORDER BY p.id), '')) INTO v_n, v_md5
    FROM public.places p WHERE p.category IS DISTINCT FROM 'beach';
  IF v_n <> (b->>'nb_n')::bigint OR v_md5 IS DISTINCT FROM b->>'nb_md5' THEN RAISE EXCEPTION 'scope: non-beach places changed (count % -> %, checksum equal: %)', b->>'nb_n', v_n, v_md5 IS NOT DISTINCT FROM b->>'nb_md5'; END IF;
  SELECT count(*), md5(coalesce(string_agg(to_jsonb(p)::text, '|' ORDER BY p.id), '')) INTO v_n, v_md5
    FROM public.places p WHERE p.category IS NOT DISTINCT FROM 'beach' AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id);
  IF v_n <> (b->>'ob_n')::bigint OR v_md5 IS DISTINCT FROM b->>'ob_md5' THEN RAISE EXCEPTION 'scope: other beaches changed (count % -> %, checksum equal: %)', b->>'ob_n', v_n, v_md5 IS NOT DISTINCT FROM b->>'ob_md5'; END IF;
  SELECT count(*), md5(coalesce(string_agg(to_jsonb(p)::text, '|' ORDER BY p.id), '')) INTO v_n, v_md5
    FROM public.places p WHERE p.status IS NOT DISTINCT FROM 'active';
  IF v_n <> (b->>'act_n')::bigint OR v_md5 IS DISTINCT FROM b->>'act_md5' THEN RAISE EXCEPTION 'this file must publish nothing: the set of active rows changed (count % -> %, checksum equal: %)', b->>'act_n', v_n, v_md5 IS NOT DISTINCT FROM b->>'act_md5'; END IF;

  -- rows added now, measured as table growth, plus rows that were already there = the file's pairs; a row that held a pair before must be
  -- THIS file's row (a beach with the file's source and source_id; while still staged, also the file's name — an admin may rename a published
  -- beach later without failing a re-run) — counts only, never the foreign row's values
  SELECT count(*) INTO v_total_after FROM public.places;
  v_added := v_total_after - (b->>'total')::bigint;
  IF v_added + (b->>'present')::int <> v_expect THEN
    RAISE EXCEPTION 'rows added now (%) + rows present before (%) <> % pairs in this file', v_added, b->>'present', v_expect; END IF;
  IF (b->>'present')::int > 0 THEN
    SELECT count(*) INTO v_n FROM public.places p JOIN jsonb_array_elements(v_pairs) e
        ON e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id
      WHERE p.category IS DISTINCT FROM 'beach' OR (p.status = 'staged' AND p.name IS DISTINCT FROM e->>2);
    IF v_n <> 0 THEN RAISE EXCEPTION '% of the % rows that held this file''s pairs before are not this file''s rows (not a beach, or a staged row under another name)', v_n, b->>'present'; END IF;
  END IF;

  -- c. content of the rows that are still staged (a later, legitimate edit of a published row must not fail a re-run)
  SELECT count(*) INTO v_n FROM public.places p WHERE p.category IS NOT DISTINCT FROM 'beach' AND p.status = 'staged' AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id)
    AND (p.blue_flag IS NOT NULL OR p.cover_image_url IS NOT NULL OR cardinality(coalesce(p.photos, '{}')) > 0 OR p.photo_credits IS NOT NULL OR p.photo_attribution IS NOT NULL
         OR p.provider_id IS NOT NULL OR p.submitted_by IS NOT NULL OR p.hidden_at IS NOT NULL OR p.featured_until IS NOT NULL OR p.official_visit IS NOT NULL
         OR (p.source IS DISTINCT FROM 'visitncy_beaches' AND (p.description_i18n IS NOT NULL OR p.amenities IS NOT NULL OR p.access_type IS NOT NULL)));
  IF v_n <> 0 THEN RAISE EXCEPTION '% staged rows carry a field this file never writes (blue_flag, photos, owner, or a Ministry-only field on an OSM row)', v_n; END IF;
  SELECT count(*) INTO v_n FROM public.places p WHERE p.category IS NOT DISTINCT FROM 'beach' AND p.status = 'staged' AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id)
    AND (jsonb_typeof(p.name_i18n) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p.name_i18n)) <> 9
         OR NOT (p.name_i18n ?& ARRAY['en','tr','ar','ru','el','fr','es','de','fa']));
  IF v_n <> 0 THEN RAISE EXCEPTION '% staged rows lack the 9 name_i18n keys', v_n; END IF;
  SELECT count(*) INTO v_n FROM public.places p WHERE p.category IS NOT DISTINCT FROM 'beach' AND p.status = 'staged' AND p.source = 'visitncy_beaches' AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id)
    AND (jsonb_typeof(p.description_i18n) IS DISTINCT FROM 'object' OR NOT (p.description_i18n ?& ARRAY['en','tr','ar','ru','el','fr','es','de','fa']));
  IF v_n <> 0 THEN RAISE EXCEPTION '% staged Ministry rows lack the 9 description_i18n keys', v_n; END IF;
  RAISE NOTICE '20261207 a/b/c OK: % of % rows present (% added now, % Ministry), nothing else touched, nothing published', v_present_after, v_expect, v_added, v_min;
END $$;

-- ─── Assertions d and e: the policies that decide who can read a staged row, and the triggers an INSERT fires ───
-- Read from pg_policies / pg_trigger (the live catalogs), not from the migration files; the expectations below come from
-- supabase/migrations 20260822 (7 policies), 20260824 (places_hide_reported), 20261178 (places_select_preview_staged).
DO $$
DECLARE
  v_n int; v_read int; v_perm int; v_restr int; v_names text; v_q text; v_trg_n int; v_trg_names text; v_trg_bad int;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE permissive = 'PERMISSIVE'), count(*) FILTER (WHERE permissive = 'RESTRICTIVE'),
         string_agg(policyname || ':' || cmd || ':' || permissive, ', ' ORDER BY policyname)
    INTO v_n, v_perm, v_restr, v_names FROM pg_policies WHERE schemaname = 'public' AND tablename = 'places';
  IF v_n <> 9 OR v_perm <> 5 OR v_restr <> 4 THEN
    RAISE EXCEPTION 'places has % policies (% permissive, % restrictive), expected 9 (5, 4): %', v_n, v_perm, v_restr, v_names; END IF;

  SELECT qual INTO v_q FROM pg_policies WHERE schemaname = 'public' AND tablename = 'places'
     AND policyname = 'places_select_preview_staged' AND cmd = 'SELECT' AND permissive = 'PERMISSIVE' AND with_check IS NULL;
  IF v_q IS NULL OR v_q NOT LIKE '%''staged''%' OR v_q NOT LIKE '%is_previewer()%' THEN
    RAISE EXCEPTION 'places_select_preview_staged missing or wrong (policies: %)', v_names; END IF;
  IF EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'places'
              AND policyname <> 'places_select_preview_staged' AND coalesce(qual, '') || coalesce(with_check, '') LIKE '%staged%') THEN
    RAISE EXCEPTION 'another places policy mentions staged (policies: %)', v_names; END IF;
  -- positive control: the public read is unchanged — still 'active' (+ own / owned / admin)
  SELECT qual INTO v_q FROM pg_policies WHERE schemaname = 'public' AND tablename = 'places' AND policyname = 'places_select' AND cmd = 'SELECT' AND permissive = 'PERMISSIVE';
  IF v_q IS NULL OR v_q NOT LIKE '%''active''%' THEN RAISE EXCEPTION 'places_select lost its active arm (policies: %)', v_names; END IF;
  -- permissive-OR: exactly the two read policies, nothing else can open a row
  SELECT count(*) INTO v_read FROM pg_policies WHERE schemaname = 'public' AND tablename = 'places' AND permissive = 'PERMISSIVE' AND cmd IN ('SELECT', 'ALL');
  IF v_read <> 2 THEN RAISE EXCEPTION '% permissive read policies on places, expected 2: %', v_read, v_names; END IF;

  -- e. INSERT-firing triggers: tgtype bit 4 = INSERT, bit 2 = BEFORE, bit 1 = ROW; internal (FK) triggers excluded
  SELECT count(*), string_agg(tgname, ', ' ORDER BY tgname), count(*) FILTER (WHERE (tgtype & 3) <> 3)
    INTO v_trg_n, v_trg_names, v_trg_bad
    FROM pg_trigger WHERE tgrelid = 'public.places'::regclass AND NOT tgisinternal AND tgenabled <> 'D' AND (tgtype & 4) <> 0;
  IF v_trg_n <> 4 OR v_trg_bad <> 0 THEN
    RAISE EXCEPTION 'places has % enabled INSERT triggers (% not BEFORE ROW), expected 4 BEFORE ROW: %', v_trg_n, v_trg_bad, v_trg_names; END IF;
  RAISE NOTICE '20261207 d/e OK: places policies (%): %; INSERT triggers (%): %', v_n, v_names, v_trg_n, v_trg_names;
END $$;

-- ─── Assertion f: BEHAVIOUR, not text — what anon and authenticated sessions (no preview header) can actually read ───
-- The policy text assertions above can be fooled (a rewritten places_select, an is_previewer() that returns true); this asks the database.
-- Four sessions: anon; authenticated with no claims; a normal signed-in user and a guest, each with a JWT claims setting shaped as in
-- 20261068 (random sub matching no row, role authenticated; the guest also is_anonymous true, which is what is_anonymous_session() reads), so
-- auth.uid() is not NULL and a policy that widens on a session is caught. Admins are not tested here: their is_admin() arm is intended.
-- SET LOCAL ROLE reverts at COMMIT/ROLLBACK; the way back is SET LOCAL ROLE postgres (RESET ROLE would drop to the login role mid-transaction).
-- Counts are captured while in the role and RAISEd only after switching back; the claims setting is cleared before returning to postgres.
DO $$
DECLARE
  v_pairs jsonb := (current_setting('ada.beaches_before')::jsonb)->'pairs';
  v_file int[] := ARRAY[0, 0, 0, 0]; v_live int[] := ARRAY[0, 0, 0, 0];
  v_kinds text[] := ARRAY['anon', 'authenticated without claims', 'signed-in user', 'guest'];
  v_claims text[] := ARRAY[NULL, '', NULL, NULL];
  v_i int; v_f int; v_l int;
BEGIN
  v_claims[3] := json_build_object('sub', gen_random_uuid(), 'role', 'authenticated')::text;
  v_claims[4] := json_build_object('sub', gen_random_uuid(), 'role', 'authenticated', 'is_anonymous', true)::text;
  FOR v_i IN 1..4 LOOP
    IF v_i = 1 THEN SET LOCAL ROLE anon; ELSE SET LOCAL ROLE authenticated; PERFORM set_config('request.jwt.claims', v_claims[v_i], true); END IF;
    SELECT count(*) INTO v_f FROM public.places p WHERE p.status = 'staged' AND EXISTS (
      SELECT 1 FROM jsonb_array_elements(v_pairs) e WHERE e->>0 IS NOT DISTINCT FROM p.source AND e->>1 IS NOT DISTINCT FROM p.source_id);
    SELECT count(*) INTO v_l FROM public.places WHERE category = 'beach' AND status = 'active';
    v_file[v_i] := v_f; v_live[v_i] := v_l;
    PERFORM set_config('request.jwt.claims', '', true);
    SET LOCAL ROLE postgres;
  END LOOP;
  IF current_user IS DISTINCT FROM 'postgres' THEN RAISE EXCEPTION 'visibility check could not return to role postgres'; END IF;
  FOR v_i IN 1..4 LOOP
    IF v_file[v_i] <> 0 THEN RAISE EXCEPTION '% can read % of this file''s staged rows (staged rows must be invisible without the preview key)', v_kinds[v_i], v_file[v_i]; END IF;
  END LOOP;
  FOR v_i IN 1..4 LOOP
    IF v_live[v_i] <= 0 THEN RAISE EXCEPTION 'positive control failed: % sees % active beaches', v_kinds[v_i], v_live[v_i]; END IF;
  END LOOP;
  RAISE NOTICE '20261207 f OK: anon, authenticated without claims, a signed-in user and a guest each read 0 of this file''s staged rows and %/%/%/% active beaches (positive control)', v_live[1], v_live[2], v_live[3], v_live[4];
END $$;

